# Constrain with conditions rather than guessing at narrower actions
{
  "Effect": "Allow",
  "Action": ["s3:GetObject", "s3:PutObject"],
  "Resource": "arn:aws:s3:::billing-exports/prod/*",
  "Condition": {
    "StringEquals": {"aws:PrincipalTag/team": "billing"},
    "Bool": {"aws:SecureTransport": "true"}
  }
}

# Verify effective access as the caller
kubectl auth can-i --list --as=system:serviceaccount:app:reporting -n app

# Do not hand a token to a pod that never calls the API server
apiVersion: v1
kind: ServiceAccount
metadata: {name: reporting, namespace: app}
automountServiceAccountToken: false
